  'pub.desk.THERMAL.sub': { en: 'Buxar Thermal Power Plant (1320 MW)', hi: 'बक्सर ताप विद्युत संयंत्र (1320 मेगावाट)', gu: 'બક્સર થર્મલ પાવર પ્લાન્ટ (1320 MW)', mr: 'बक्सर औष्णिक वीज प्रकल्प (1320 मेगावॅट)' },
  'pub.desk.THERMAL.desc': { en: 'Commercial invoicing, capacity charges, Energy Charge Rate (ECR) computations, coal blending, and beneficiary surplus management.', hi: 'वाणिज्यिक बीजक, क्षमता प्रभार, ऊर्जा प्रभार दर (ईसीआर) गणना, कोयला मिश्रण एवं लाभार्थी अधिशेष प्रबंधन।', gu: 'કમર્શિયલ ઇન્વૉઇસિંગ, ક્ષમતા ચાર્જ, ઊર્જા ચાર્જ દર (ECR) ગણતરી, કોલસા મિશ્રણ અને લાભાર્થી વધારાનું સંચાલન.', mr: 'व्यावसायिक इनव्हॉइसिंग, क्षमता शुल्क, ऊर्जा शुल्क दर (ECR) गणना, कोळसा मिश्रण आणि लाभार्थी अधिशेष व्यवस्थापन.' },
  'pub.desk.THERMAL.f1': { en: 'Fixed & Energy Charge (ECR) Invoicing Framework', hi: 'स्थिर एवं ऊर्जा प्रभार (ईसीआर) बीजक ढाँचा', gu: 'સ્થિર અને ઊર્જા ચાર્જ (ECR) ઇન્વૉઇસિંગ માળખું', mr: 'स्थिर व ऊर्जा शुल्क (ECR) इनव्हॉइसिंग चौकट' },
  'pub.desk.THERMAL.f2': { en: 'Coal Blending Transit & Stock Accounting', hi: 'कोयला मिश्रण पारगमन एवं स्टॉक लेखा', gu: 'કોલસા મિશ્રણ ટ્રાન્ઝિટ અને સ્ટોક હિસાબ', mr: 'कोळसा मिश्रण वाहतूक व साठा लेखा' },
