  'pub.desk.THERMAL.f4': { en: 'Daily Generation Registers & Month Close', hi: 'दैनिक उत्पादन रजिस्टर एवं मासिक समापन', gu: 'દૈનિક ઉત્પાદન રજિસ્ટર અને માસિક ક્લોઝ', mr: 'दैनिक उत्पादन नोंदवह्या व मासिक समापन' },
  'pub.desk.THERMAL.f5': { en: 'Beneficiary Scheduling & Tripartite Settlement', hi: 'लाभार्थी अनुसूचन एवं त्रिपक्षीय निपटान', gu: 'લાભાર્થી શેડ્યુલિંગ અને ત્રિપક્ષીય સેટલમેન્ટ', mr: 'लाभार्थी वेळापत्रक व त्रिपक्षीय सेटलमेंट' },
  'pub.asset.NJHPS.badge': { en: 'Hydro Baseload', hi: 'जल विद्युत आधार भार', gu: 'હાઇડ્રો બેઝલોડ', mr: 'जलविद्युत बेसलोड' },
  'pub.asset.NJHPS.desc': { en: 'India\'s flagship underground hydroelectric station with a design energy of ~6,950 MUs a year.', hi: 'भारत का प्रमुख भूमिगत जलविद्युत केंद्र, वार्षिक अभिकल्पित ऊर्जा लगभग 6,950 एमयू।', gu: 'ભારતનું મુખ્ય ભૂગર્ભ જળવિદ્યુત મથક, વાર્ષિક ડિઝાઇન ઊર્જા આશરે 6,950 MU.', mr: 'भारतातील प्रमुख भूमिगत जलविद्युत केंद्र, वार्षिक अभिकल्पित ऊर्जा सुमारे 6,950 MU.' },
  'pub.asset.RAMPUR.badge': { en: 'Cascade Hydro', hi: 'सोपानी जल विद्युत', gu: 'કેસ્કેડ હાઇડ્રો', mr: 'कॅस्केड जलविद्युत' },
  'pub.asset.RAMPUR.desc': { en: 'Eco-friendly tandem cascade operating downstream of Nathpa Jhakri, harnessing tailrace discharge with zero water loss.', hi: 'नाथपा झाकड़ी के निचले प्रवाह में संचालित पर्यावरण-अनुकूल सोपानी केंद्र, जो बिना जल हानि के पश्च-प्रवाह का उपयोग करता है।', gu: 'નાથપા ઝાકરીના નીચાણમાં કાર્યરત પર્યાવરણ-અનુકૂળ કેસ્કેડ મથક, જે પાણીના નુકસાન વિના ટેઇલરેસ ડિસ્ચાર્જનો ઉપયોગ કરે છે.', mr: 'नाथपा झाकरीच्या खालच्या प्रवाहात कार्यरत पर्यावरणपूरक कॅस्केड केंद्र, जे पाण्याचे नुकसान न करता टेलरेस विसर्गाचा वापर करते.' },
  'pub.asset.BUXAR.badge': { en: 'Supercritical Thermal', hi: 'सुपरक्रिटिकल ताप विद्युत', gu: 'સુપરક્રિટિકલ થર્મલ', mr: 'सुपरक्रिटिकल औष्णिक' },
  'pub.asset.BUXAR.desc': { en: 'High-efficiency supercritical station delivering vital baseload security to Eastern and Northern grid beneficiaries.', hi: 'उच्च दक्षता वाला सुपरक्रिटिकल केंद्र, जो पूर्वी एवं उत्तरी ग्रिड लाभार्थियों को आधार भार सुरक्षा देता है।', gu: 'ઉચ્ચ કાર્યક્ષમતાવાળું સુપરક્રિટિકલ મથક, જે પૂર્વ અને ઉત્તર ગ્રિડ લાભાર્થીઓને બેઝલોડ સુરક્ષા આપે છે.', mr: 'उच्च कार्यक्षमतेचे सुपरक्रिटिकल केंद्र, जे पूर्व व उत्तर ग्रिड लाभार्थ्यांना बेसलोड सुरक्षा देते.' },
  'pub.asset.REIA_PORTFOLIO.badge': { en: 'MNRE Mandate', hi: 'एमएनआरई अधिदेश', gu: 'MNRE આદેશ', mr: 'MNRE आदेश' },
  'pub.asset.REIA_PORTFOLIO.desc': { en: 'Central agency designated by MNRE for utility-scale renewable bidding, back-to-back 25-yr PPAs/PSAs, and deviation billing.', hi: 'यूटिलिटी-स्तरीय नवीकरणीय बोली, बैक-टू-बैक 25-वर्षीय पीपीए/पीएसए एवं विचलन बिलिंग हेतु एमएनआरई द्वारा नामित केंद्रीय एजेंसी।', gu: 'યુટિલિટી-સ્કેલ નવીનીકરણીય બિડિંગ, બેક-ટુ-બેક 25-વર્ષીય PPA/PSA અને ડેવિએશન બિલિંગ માટે MNRE દ્વારા નિયુક્ત કેન્દ્રીય એજન્સી.', mr: 'युटिलिटी-स्तरीय नवीकरणीय बोली, बॅक-टू-बॅक 25-वर्षीय PPA/PSA आणि विचलन बिलिंगसाठी MNRE ने नियुक्त केलेली केंद्रीय संस्था.' },

