  'pub.policy.manageCookies': { en: 'Manage Cookie Preferences', hi: 'कुकी प्राथमिकताएँ प्रबंधित करें', gu: 'કૂકી પસંદગીઓ સંચાલિત કરો', mr: 'कुकी प्राधान्ये व्यवस्थापित करा' },
  'pub.policy.cookieConsent': { en: 'You may update or withdraw your consent for optional performance analytics cookies at any time.', hi: 'आप इस प्लेटफ़ॉर्म पर प्रदर्शन कुकीज़ के लिए अपनी सहमति को किसी भी समय अपडेट या वापस ले सकते हैं।', gu: 'તમે વૈકલ્પિક પર્ફોર્મન્સ એનાલિટિક્સ કૂકીઝ માટેની તમારી સંમતિ ગમે ત્યારે અપડેટ અથવા પાછી ખેંચી શકો છો.', mr: 'आपण ऐच्छिक कामगिरी विश्लेषण कुकीजसाठीची आपली संमती कधीही अद्ययावत किंवा मागे घेऊ शकता.' },
