  'pub.sitemap.cookieDesc': { en: 'Review and configure DPDP browser cookie storage', hi: 'ब्राउज़र कुकी एवं सहमति प्राथमिकताएं संशोधित करें', gu: 'DPDP બ્રાઉઝર કૂકી સંગ્રહની સમીક્ષા અને ગોઠવણી કરો', mr: 'DPDP ब्राउझर कुकी साठवणुकीचा आढावा घ्या व ती कॉन्फिगर करा' },
