  'fb.err.consent': { en: 'Tick the box so we can reply to you.', hi: 'चेकबॉक्स चिह्नित करें ताकि हम आपको उत्तर दे सकें।', gu: "બોક્સ પર ટિક કરો જેથી અમે તમને જવાબ આપી શકીએ.", mr: "आम्ही उत्तर देऊ शकू म्हणून चौकटीत खूण करा." },
  'fb.err.server': { en: 'The feedback could not be sent. Try again, or write to the Web Information Manager.', hi: 'प्रतिक्रिया नहीं भेजी जा सकी। पुनः प्रयास करें या वेब सूचना प्रबंधक को लिखें।', gu: "પ્રતિસાદ મોકલી શકાયો નહીં. ફરી પ્રયાસ કરો અથવા વેબ માહિતી વ્યવસ્થાપકને લખો.", mr: "अभिप्राय पाठवता आला नाही. पुन्हा प्रयत्न करा किंवा वेब माहिती व्यवस्थापकाला लिहा." },
